attributes.twig:
{# 
Last updated by Dylan 5/01/2026. Adding conditional to restrict downloads to NYPR staff or administrators
Updated Apri 29th 2026 by Diego. Renders either a single Physical instantiation
or a list of Files per Digital as a "row" #}
{% if node.id %}
 {# get any media attached #}
 {# -- Role-based download restriction: only NYPR staff and administrators may download files -- #}
 {% set downloads_allowed = 'nypr_staff' in user_roles or 'administrator' in user_roles %}
   {% if data.type == "PhysicalInstantiation" %}
    <div class="row border-bottom py-2">
      <div class="col-2 border-end">Physical</div>
      <div class="col-2 border-end">{{ data.physical_description[0] ? data.physical_description[0] : (data.medium[0] ? data.medium[0] : "Unknown") }}</div>
    {% set nodeurl = url('entity.node.canonical', {'node': node.id}, {'absolute': false}) %}
    {% set link = '<a class="text-truncate d-inline-block w-100" href="' ~ nodeurl|render ~ '">' ~  (data.label_alt ? data.label_alt : data.label) ~ '</a>' %}
      <div class="col-3 border-end">{{ link|raw }}</div>
      <div class="col-3 border-end">
        <a href="https://docs.google.com/forms/d/e/1FAIpQLSdBySgUKlLn5La7aC5f16LwBFNaJwmMjg2TAGwuJnZ_-gFpEQ/viewform" target="_blank">Request</a>
      </div>
      <div class="col-2 border-end"></div>
   </div>
   {% else %}   
	{% set file_data = [] %}
     {% if attribute(data, 'as:document')|length > 0 %} 
      {% for file in attribute(data, 'as:document') %}
        {% if file['dr:mimetype']!= "application/json" %}
		  {% set url = "/do/" ~ node.uuid.value  ~ "/file/" ~ file['dr:uuid'] ~"/download/" ~ file.name|url_encode %}
          {% set type = file['dr:mimetype'] %}
          {% set name = file.name %}
          {% set play = false %}
          {% set file_data = file_data|merge([{"url":url, "type":type, "name":name, "play": play}]) %}
        {% endif %}   
	  {% endfor %} 
    {% endif %} 
    {% if attribute(data, 'as:text')|length > 0 %} 
      {% for file in attribute(data, 'as:text') %} 
		{% set url = "/do/" ~ node.uuid.value  ~ "/file/" ~ file['dr:uuid'] ~"/download/" ~ file.name|url_encode %}
        {% set type = file['dr:mimetype'] %}
        {% set name = file.name %}
        {% set play = false %}
        {% set file_data = file_data|merge([{"url":url, "type":type, "name":name, "play": play}]) %}
	  {% endfor %} 
    {% endif %} 
    {% if attribute(data, 'as:image')|length > 0 %} 
	 {% for file in attribute(data, 'as:image') %} 
		{% set url = "/do/" ~ node.uuid.value  ~ "/file/" ~ file['dr:uuid'] ~"/download/" ~ file.name|url_encode %}
        {% set type = file['dr:mimetype'] %}
        {% set name = file.name %}
        {% set play = false %}
        {% set file_data = file_data|merge([{"url":url, "type":type, "name":name, "play": play}]) %}
	  {% endfor %} 
    {% endif %} 
    {% if attribute(data, 'as:audio')|length > 0 %} 
      {% for file in attribute(data, 'as:audio') %} 
		{% set url = "/do/" ~ node.uuid.value  ~ "/file/" ~ file['dr:uuid'] ~"/download/" ~ file.name|url_encode %}
        {% set type = file['dr:mimetype'] %}
        {% set name = file.name %}
        {% set play = true %}
        {% set file_data = file_data|merge([{"url":url, "type":type, "name":name, "play": play}]) %} 
	  {% endfor %} 
    {% endif %} 
    {% if attribute(data, 'as:video')|length > 0 %} 
      {% for file in attribute(data, 'as:video') %} 
		{% set url = "/do/" ~ node.uuid.value  ~ "/file/" ~ file['dr:uuid'] ~"/download/" ~ file.name|url_encode %}
        {% set type = file['dr:mimetype'] %}
        {% set name = file.name %}
        {% set play = true %}
        {% set file_data = file_data|merge([{"url":url, "type":type, "name":name, "play": play}]) %} 
	  {% endfor %} 
    {% endif %} 
    {% if attribute(data, 'as:text')|length > 0 %} 
     {% for file in attribute(data, 'as:text') %} 
		{% set url = "/do/" ~ node.uuid.value  ~ "/file/" ~ file['dr:uuid'] ~"/download/" ~ file.name|url_encode %}
        {% set name = file.name %}
        {% set type = file['dr:mimetype'] %}
        {% set play = true %}
        {% set file_data = file_data|merge([{"url":url, "type":type, "name":name, "play": play}]) %}
	  {% endfor %} 
   {% endif %} 
  {% for holdings in file_data %}
  <div class="row border-bottom py-2">
    <div class="col-2 border-end">Digital</div>
    <div class="col-2 border-end">{{ holdings["type"] }}</div>
    {% set nodeurl = url('entity.node.canonical', {'node': node.id}, {'absolute': false}) %}
    {% set link = '<a href="' ~ nodeurl|render ~ '">' ~  (data.label_alt ? data.label_alt : data.label) ~ '</a>' %}
    <div class="col-3 border-end">{{ link|raw }}</div>
    <div class="col-3 border-end">
    {% if holdings["play"] %}
        {% set render_target = "container-child-player" %}{# set and defined in https://archives.nypublicradio.org/metadatadisplay/22/edit #}
         <span id="player-trigger-{{node.id}}-{{loop.index0}}" rel="nofollow" class="btn btn-sm btn-secondary text-truncate w-100" data-sbf-view-id="ado_audio_video_player_rendered" data-sbf-view-display-id="audio_viewer" data-sbf-view-arguments="{{ node.id }}" data-sbf-view-render-target="{{ render_target }}" data-sbf-view-event="click"><i class="fa fa-play"></i>&nbsp;{{ data.label_alt ? data.label_alt : data.label }}<span>
    {% endif %}
    </div>
    <div class="col-2 border-end">{% if downloads_allowed %}<a download rel="nofollow" href="{{ holdings["url"] }}" title="Download" class="btn btn-sm btn-secondary px-2"><i class="fa fa-download"></i></a>{% endif %}</div>
 </div>
 {% endfor %}
 {% if file_data is empty %}
    <div class="row border-bottom py-2">
      <div class="col-2 border-end">Digital</div>
      <div class="col-2 border-end">{{ data.physical_description[0] ? data.physical_description[0] : (data.medium[0] ? data.medium[0] : "Unknown") }}</div>
    {% set nodeurl = url('entity.node.canonical', {'node': node.id}, {'absolute': false}) %}
    {% set link = '<a class="text-truncate d-inline-block w-100" href="' ~ nodeurl|render ~ '">' ~  (data.label_alt ? data.label_alt : data.label) ~ '</a>' %}
      <div class="col-3 border-end">{{ link|raw }}</div>
      <div class="col-3 border-end">Metadata Only</div>
      <div class="col-2 border-end"></div>
    </div>  
 {% endif %}
 {% endif %}
{% endif %}
